/**
 * The agent-tool entity's sub-type table (M3). Agent tools are a real
 * sub-entity — nine terraform resource types sharing one ownership shape
 * (agent_id + app_id + name/description) — so per-sub-type knowledge is one
 * ROW here, exactly like `entities/field/types.ts`.
 *
 * Every product-facing provider agent-tool resource is implemented end to
 * end. Hydra also exposes its internal select-bot-route transport type in the
 * generic GraphQL tool union; that row remains recognized so pull can report
 * it explicitly, but it is intentionally not authorable or adoptable.
 */
export const RUN_AUTOMATION_TOOL_RESOURCE_TYPE = "elementum_agent_run_automation_tool";
export const AGENT_TOOL_SUB_TYPES = [
    { typeKey: "createRecord", resourceType: "elementum_agent_create_record_tool", implemented: true },
    { typeKey: "searchAspect", resourceType: "elementum_agent_search_records_tool", implemented: true },
    { typeKey: "updateRecord", resourceType: "elementum_agent_update_record_tool", implemented: true },
    { typeKey: "searchTable", resourceType: "elementum_agent_ai_search_tool", implemented: true },
    { typeKey: "relateRecord", resourceType: "elementum_agent_relate_record_tool", implemented: true },
    { typeKey: "executeWorkflow", resourceType: RUN_AUTOMATION_TOOL_RESOURCE_TYPE, implemented: true },
    { typeKey: "runAgent", resourceType: "elementum_agent_run_agent_tool", implemented: true },
    { typeKey: "selectBotRoute", resourceType: "elementum_agent_select_bot_route_tool" },
    { typeKey: "mcp", resourceType: "elementum_agent_mcp_tool", implemented: true },
];
export const TOOL_SUB_TYPE_BY_TYPE_KEY = new Map(AGENT_TOOL_SUB_TYPES.map((t) => [t.typeKey, t]));
export const TOOL_SUB_TYPE_BY_RESOURCE = new Map(AGENT_TOOL_SUB_TYPES.map((t) => [t.resourceType, t]));
/** The resource types the terraform path round-trips today (adoption scope). */
export const IMPLEMENTED_TOOL_RESOURCE_TYPES = AGENT_TOOL_SUB_TYPES.filter((t) => t.implemented === true).map((t) => t.resourceType);
/** Every declared tool resource type — stream partition recognizes these by name. */
export const ALL_TOOL_RESOURCE_TYPES = AGENT_TOOL_SUB_TYPES.map((t) => t.resourceType);
/**
 * EDK's tool-name rule — enforced in the authoring builders (see
 * `entities/agent/tools.ts`), never in the tf passes. It is deliberately
 * STRICTER than the platform's own (`[A-Za-z0-9_-]`, which also tolerates
 * hyphens): EDK requires underscores so an authored name maps 1:1 to its
 * terraform label — a hyphenated name sanitizes to a different label and breaks
 * the name↔label correspondence. 1–64 chars of letters, digits, and
 * underscores; no consecutive underscores (the platform rejects those, opaquely).
 * `from-tf` does NOT apply this — a hyphenated tool deployed outside EDK must
 * still be pullable.
 */
export function isValidToolName(name) {
    return /^[A-Za-z0-9_]{1,64}$/.test(name) && !name.includes("__");
}
/** Attributes `toolFromTf` understands per implemented sub-type — growth is reported loudly. */
const COMMON_TOOL_ATTRS = ["agent_id", "app_id", "name", "description", "start_message", "run_as", "service_account_id"];
export const KNOWN_TOOL_ATTRS = {
    createRecord: new Set([...COMMON_TOOL_ATTRS, "target_id", "fields"]),
    executeWorkflow: new Set([
        ...COMMON_TOOL_ATTRS,
        "automation_id",
        "inputs",
        "outputs",
        "timeout",
    ]),
    searchAspect: new Set([
        ...COMMON_TOOL_ATTRS,
        "target_id",
        "query_description",
        "result_limit",
        "fields",
        "filter_variables",
    ]),
    updateRecord: new Set([
        ...COMMON_TOOL_ATTRS,
        "target_id",
        "handle_description",
        "fields",
    ]),
    // target_id is OPTIONAL here (unlike the other three) - confirmed live,
    // 5 of 18 real elementum_agent_ai_search_tool blocks have no target_id at
    // all. return_fields (field_id/name/display_name) is the dialect ei's own
    // export still emits on most tools; a minority have already migrated to
    // the newer `fields` (field_id/name/description) shape the provider
    // schema is deprecating return_fields in favor of - both must round-trip,
    // since re-emitting the wrong one on an already-migrated tool would plan
    // a spurious diff on every apply.
    searchTable: new Set([
        ...COMMON_TOOL_ATTRS,
        "target_id",
        "search_table_id",
        "query_description",
        "result_limit",
        "fields",
        "filter_variables",
        "return_fields",
    ]),
    relateRecord: new Set([
        ...COMMON_TOOL_ATTRS,
        "target_id",
        "related_target_id",
    ]),
    runAgent: new Set([
        ...COMMON_TOOL_ATTRS,
        "target_agent_id",
        "worker_task_prompt",
    ]),
    selectBotRoute: new Set([...COMMON_TOOL_ATTRS, "bot_id"]),
    mcp: new Set([
        ...COMMON_TOOL_ATTRS,
        "server_url",
        "mcp_tool_name",
        "headers",
    ]),
};
